html:
{%- set print = get_print_settings() -%}
{%- set totals = get_print_totals(doc) -%}
<style>
  .books-print { background: #fff; color: #171717; font-size: 16px; line-height: 24px; }
  .books-print table { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .books-print td, .books-print th { padding: 0; border: 0; color: inherit; text-align: left; vertical-align: top; font-weight: inherit; }
  .books-print .books-right { text-align: right; }
  .books-print .books-bold { font-weight: bold; }
  .books-print .books-header { background: #f3f3f3; padding: 40px 48px; }
  .books-print .books-logo, .books-print .books-company-text { display: inline-block; vertical-align: middle; }
  .books-print .books-logo { max-height: 48px; max-width: 128px; margin-right: 16px; }
  .books-print .books-company-name { font-size: 17px; line-height: 22.95px; font-weight: bold; letter-spacing: 0.02em; }
  .books-print .books-small { font-size: 13px; line-height: 17.55px; color: #383838; letter-spacing: 0.02em; }
  .books-print .books-details { margin-top: 32px; line-height: 24px; letter-spacing: 0.02em; }
  .books-print .books-details th { width: 33.333%; font-weight: bold; }
  .books-print .books-details td { color: #383838; }
  .books-print .books-details tr + tr > * { padding-top: 16px; }
  .books-print .books-time { margin-left: 8px; }
  .books-print .books-body { padding: 48px 48px 0; line-height: 21.6px; letter-spacing: 0.02em; }
  .books-print .books-footer { padding: 48px; line-height: 21.6px; letter-spacing: 0.02em; }
  .books-print .books-band { margin: 0 -16px; }
  .books-print .books-band table { table-layout: auto; }
  .books-print .books-band td { white-space: nowrap; text-align: right; }
  .books-print .books-band .books-spacer { width: 100%; }
  .books-print .books-band .books-total { padding: 12px 32px 12px 0; }
  .books-print .books-band .books-grand-total { padding: 12px 16px; color: #fff; }
  .books-print .books-label { line-height: 24px; }
  .books-print .books-total-label { color: #383838; }
  .books-print .books-total-value { margin-top: 8px; font-size: 17px; line-height: 22.95px; letter-spacing: 0.02em; }
  .books-print .books-grand-total-value { margin-top: 8px; font-size: 18px; line-height: 24.3px; font-weight: bold; letter-spacing: 0.01em; }
  .books-print .books-in-words { margin-top: 16px; line-height: 24px; text-align: right; }
  .books-print .books-note { margin-top: 48px; }
  .books-print .books-note-text { margin-top: 16px; white-space: pre-line; }
  .books-print .books-fields { line-height: 24px; }
  .books-print .books-fields th { width: 33.333%; font-weight: bold; }
  .books-print .books-fields td { color: #383838; }
  .books-print .books-fields > tbody > tr + tr > * { padding-top: 16px; }
  .books-print .books-tax-summary { width: 50%; table-layout: auto; }
  .books-print .books-band { background: #f3f3f3; }
</style>
<main class="books-print" style="font-family: {{ print.font }}">
  <header class="books-header">
    <div class="books-company">
      {%- if print.display_logo and print.logo %}<img class="books-logo" src="{{ print.logo }}">{% endif -%}
      <div class="books-company-text">
        <div class="books-company-name" style="color: {{ print.color }}">{{ (print.company_name or "") | e }}</div>
        {%- if print.address %}
        <div class="books-small">{{ print.address | e }}</div>
        {%- endif %}
        {%- if print.gstin %}
        <div class="books-small">{{ _("GSTIN") }}: {{ print.gstin | e }}</div>
        {%- endif %}
      </div>
    </div>
    <table class="books-details">
      <tr>
        <th>{{ _("Payment") }}</th>
        <td>
          <div class="books-bold">{{ doc.name | e }}</div>
          <div>
            {{- books_format(doc.date, "Date") -}}
            {%- if print.display_time %}<span class="books-time">{{ frappe.utils.format_time(doc.date) }}</span>{% endif -%}
          </div>
        </td>
      </tr>
      <tr>
        <th>{{ _("Party") }}</th>
        <td>
          {%- if doc.party %}
          {%- set party = frappe.db.get_value("Books Party", doc.party, ["address", "gstin"], as_dict=True) %}
          <div class="books-bold">{{ doc.party | e }}</div>
          {%- if party.address %}
          <div>{{ (frappe.db.get_value("Books Address", party.address, "address_display") or "") | e }}</div>
          {%- endif %}
          {%- if party.gstin %}
          <div>{{ _("GSTIN") }}: {{ party.gstin | e }}</div>
          {%- endif %}
          {%- endif %}
        </td>
      </tr>
    </table>
  </header>
  <section class="books-body">
    <table class="books-fields">
      <tr>
        <th>{{ _("Payment Type") }}</th>
        <td>{{ _(doc.payment_type or "") }}</td>
      </tr>
      <tr>
        <th>{{ _("Payment Method") }}</th>
        <td>{{ (doc.payment_method or "") | e }}</td>
      </tr>
      {%- if totals.taxes %}
      <tr>
        <th>{{ _("Tax Summary") }}</th>
        <td>
          <table class="books-tax-summary">
            <tr>
              <td>{{ _("Taxable Value") }}</td>
              <td class="books-right">{{ books_format(totals.sub_total, "Currency") }}</td>
            </tr>
            {%- for tax in totals.taxes %}
            <tr>
              <td>{{ tax.account | e }}</td>
              <td class="books-right">{{ books_format(tax.amount, "Currency") }}</td>
            </tr>
            {%- endfor %}
          </table>
        </td>
      </tr>
      {%- endif %}
    </table>
  </section>

  <footer class="books-footer">
    <div class="books-band">
      <table>
        <tr>
          <td class="books-spacer"></td>
          <td class="books-total">
            <div class="books-label books-total-label">{{ _("Amount") }}</div>
            <div class="books-total-value">{{ books_format(doc.amount, "Currency") }}</div>
          </td>
          <td class="books-grand-total" style="background-color: {{ print.color }}">
            <div class="books-label">{{ _("Amount Paid") }}</div>
            <div class="books-grand-total-value">{{ books_format(doc.amount_paid, "Currency") }}</div>
          </td>
        </tr>
      </table>
    </div>

    {%- if print.amount_in_words %}
    <div class="books-in-words">
      <span class="books-bold">{{ _("Amount Paid In Words") }}:</span>
      {{ totals.amount_paid_in_words }}
    </div>
    {%- endif %}

    {%- if print.displaytermsandconditions and print.terms_and_conditions %}
    <section class="books-note">
      <div class="books-bold">{{ _("Terms and Conditions") }}</div>
      <div class="books-note-text">{{ print.terms_and_conditions | e }}</div>
    </section>
    {%- endif %}
  </footer>
</main>
